window.AUTH=window.AUTH||{};window.AUTH["23-1197"]={"d":"23-1197","id":"2025/23-1197","n":"Landor v. Louisiana Department of Corrections","briefs":[{"k":"petitioner","label":"Brief of petitioner Damon Landor","date":"2025-08-27","url":"https://www.supremecourt.gov/DocketPDF/23/23-1197/370936/20250827152933089_No.%2023-1997%20Landor%20merits%20brief.pdf","side":"pet","n":91},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2025-09-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-1197/373570/20250903162957828_23-1197tsacUnitedStates.pdf","side":"us","n":81},{"k":"respondent","label":"Brief of respondents Louisiana Department of Corrections and Public Safety, et al.","date":"2025-10-01","url":"https://www.supremecourt.gov/DocketPDF/23/23-1197/378442/20251001175639081_23-1197%20Brief%20for%20Respondents.pdf","side":"res","n":92},{"k":"reply","label":"Reply of petitioner Damon Landor","date":"2025-10-27","url":"https://www.supremecourt.gov/DocketPDF/23/23-1197/380757/20251027170828911_No.%2023-1197%20Landor%20reply%20brief.pdf","side":"pet","n":48}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/609us1r55_h315.pdf","tr":true,"items":[{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"by":{"0":"31, 48"},"q":[{"src":"brief","b":0,"text":"officers are bound by obligations imposed by the Constitution and by federal statutes that comport with the constitutional design.","cite":"527 U.S. 706, 755"},{"src":"argument","who":"Mr. Tripp","text":"-- in Rust versus Sullivan and then in Alden versus Maine as to state officers specifically is, when you go into this job, when you go into this line of work and you voluntarily agree to be an officer in a federally funded state program, then, yes, you -- you -- you implicitly -- you necessarily take it subject to the conditions that Congress has attached to the funds."},{"src":"argument","who":"Mr. Tripp","text":"I -- I think the -- the piece about being an employee -- and this is what's picked up in Rust versus Sullivan and Alden versus Maine as to state officers in particular, who also take an oath to comply with the federal Constitution and laws -- is that you are sort of taking the job sort of subject to the conditions, the sort of terms that attach to the work."}]},{"t":"case","label":"Arizonans for Off. Eng. v. Arizona","cite":"520 U.S. 43","y":1997,"id":"1996/95-974","sc":1,"by":{"0":"23"}},{"t":"case","label":"Barnes v. Gorman","cite":"536 U.S. 181","y":2002,"id":"2001/01-682","sc":1,"by":{"0":"26","1":"6, 19","2":"3, 9, 10, 20, 29"},"q":[{"src":"brief","b":2,"text":"defin[es] the scope of conduct for which funding recipients may be held liable for money damages.","cite":"536 U.S. at 186"}]},{"t":"case","label":"Barnett v. Short","cite":"129 F.4th 534","y":2025,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/129/534/","by":{"0":"28","2":"16, 17, 24"},"q":[{"src":"brief","b":0,"text":"demand[s] for clarity … are not identical,","cite":"129 F.4th 534, 542"}]},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"by":{"0":"24","3":"12"},"q":[{"src":"brief","b":0,"text":"‘[W]hen Congress includes particular language in one section of a statute but omits it in another section of the same Act,’ we generally take the choice to be deliberate.","cite":"598 U.S. 69, 78"}]},{"t":"case","label":"Bell v. Hood","cite":"327 U.S. 678","y":1946,"id":"scdb/1945-042","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"any available remedy to make good the wrong done.","cite":"327 U.S. 678, 684"}]},{"t":"case","label":"Bennett v. Kentucky Dep’t of Educ.","cite":"470 U.S. 656","y":1985,"id":"1984/83-1798","sc":1,"by":{"0":"41","1":"22"},"q":[{"src":"brief","b":0,"text":"cannot be viewed in the same manner as a bilateral contract governing a discrete transaction.","cite":"470 U.S. 656, 669"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"cannot be viewed in the same manner as a bilateral contract governing a discrete transaction.","cite":"470 U. S. 656, 669"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"statut[es] . . . expressing the judgment of Congress concerning desirable pub- Page Proof Pending Publication lic policy.","cite":"470 U. S., at 669"}]},{"t":"case","label":"Bondi v. VanDerStok","cite":"145 S. Ct. 857","y":2025,"id":"2024/23-852","sc":1,"by":{"0":"16"}},{"t":"case","label":"Buckelew v. Gore","cite":"2023 WL 4056043","y":2023,"court":"S.D. Cal. June 16","by":{"0":"22"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"by":{"0":"17","1":"14"}},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"by":{"0":"37"},"q":[{"src":"brief","b":0,"text":"It is almost axiomatic that the threat of damages has a deterrent effect, … particularly so when the individual official faces personal financial liability.","cite":"446 U.S. 14, 21"}]},{"t":"case","label":"City of Boerne v. Flores","cite":"521 U.S. 507","y":1997,"id":"1996/95-2074","sc":1,"by":{"0":"6","1":"4","2":"31","3":"2, 4, 6, 7, 10"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"It is instead to tell Congress to act exactly like it did in 1993 after Smith and in 2000 after City of Boerne, which is to pass new legislation, supersede Sossamon, and amend RLUIPA to allow for damages against the states, and then the states can decide, each state for itself, whether it accepts that express condition."}]},{"t":"case","label":"Cummings v. Premier Rehab Keller, P.L.L.C.","cite":"596 U.S. 212","y":2022,"id":"2021/20-219","sc":1,"by":{"0":"26, 40","1":"22, 24, 28, 34","2":"2, 9, 10, 20, 29, 32, 37, 47"},"q":[{"src":"brief","b":1,"text":"funding recipient is on notice that, by accepting federal funding, it exposes itself to liability of that nature.","cite":"596 U.S. 212, 220"},{"src":"brief","b":1,"text":"ensur[e] that the receiving entity of federal funds had notice","cite":"596 U.S. at 219"},{"src":"brief","b":2,"text":"A particular remedy is [] ‘appropriate relief’ in a private Spending Clause action ‘only if the funding recipient is on notice that, by accepting federal funding, it exposes itself to liability of that nature.","cite":"596 U.S. at 220"},{"src":"brief","b":2,"text":"‘clearly understand ... the obligations’ that would come along with doing so","cite":"596 U.S. at 219"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"only as a potential limitation on liability,","cite":"596 U. S., at 225"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"wonder . . . what sort of penalties might be on the table","cite":"596 U. S. 212, 220"},{"src":"argument","who":"Chief Justice Roberts","text":"His view of the Spending Clause would mean that foundational cases like Pennhurst and Cummings were confused, Mr. Chief Justice, because Congress can actually impose spending conditions on non-recipients too."},{"src":"argument","who":"Justice Jackson","text":"AGUI�AGA: Your Honor, it matters here because of cases like Cummings that trace all the way back to Pennhurst that say the very legitimacy of Congress's exercise of Spending Clause authority depends on that bilateral agreement."},{"src":"argument","who":"Justice Sotomayor","text":"I was surprised to hear the federal government say you look at the time of enactment, when Arlington Central, Justice Alito's opinion for the Court, and then Cummings, the Chief Justice's opinion for the Court, said you look at when the official is deciding whether to receive federal funds, what would that --"}]},{"t":"case","label":"Curtis v. Loether","cite":"415 U.S. 189","y":1974,"id":"1973/72-1035","sc":1,"by":{"0":"38"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"by":{"0":"6, 20, 33","1":"4, 20, 23, 24"},"q":[{"src":"brief","b":0,"text":"secur[ing] redress for inmates who encountered undue barriers to their religious observances.","cite":"544 U.S. at 716"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"recognized, however, that the political branches could shield religious exercise through legislative accommodation.","cite":"544 U. S. 709, 714"}]},{"t":"case","label":"Dep’t of Agric. Rural Dev. Rural Hous. Serv. v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"by":{"0":"29","3":"9"},"q":[{"src":"opinion","who":"Justice Jackson, dissenting","text":"from any of its liability provisions.","cite":"601 U. S. 42, 62"}]},{"t":"case","label":"Dixson v. United States","cite":"465 U.S. 482","y":1984,"id":"1983/82-5279","sc":1,"by":{"0":"14, 39, 41, 43","3":"10, 13, 14, 18, 19, 22"},"q":[{"src":"argument","who":"Mr. Tripp","text":"One is to follow the path that this Court has set forth in -- in Salinas in particular, Salinas, Dixson, Laudani, and Hess, and to just hold that --"},{"src":"argument","who":"Mr. Tripp","text":"And I think that's why, when this Court has had these cases, Salinas, Dixson, Hess, Laudani, it's a whole line of cases involving officers, agents, employees, subcontractors, where there's this chain of privity --"},{"src":"argument","who":"Mr. Tripp","text":"And I think what they haven't come up with is any kind of reasoned explanation why Congress can impose the condition on them but then can't enforce it, especially through civil liability, when this Court in Salinas, Dixson, Hess, and Laudani has -- has already done that and actually gone farther, and I think Sabri goes considerably farther."}]},{"t":"case","label":"Domino v. Goodwin","cite":"2024 WL 4575368","y":2024,"court":"W.D. La. July 2","by":{"0":"22"}},{"t":"case","label":"Employment Division v. Smith","cite":"494 U.S. 872","y":1990,"id":"1989/88-1213","sc":1,"by":{"0":"1, 2, 3, 4, 5, 6, 7, 12, 17, 19","1":"3, 4","2":"34","3":"2, 3, 4, 7, 10, 15, 19, 21, 24"},"q":[{"src":"brief","b":2,"text":"Congress’ second attempt to accord heightened statutory protection to religious exercise in the wake of this Court’s decision in","cite":"494 U.S. 872"},{"src":"argument","who":"Mr. Tripp","text":"I mean, I think, under -- under this -- this Court's decision in Employment Division against Smith, there is -- there is some daylight. And the -- the crux of this law, I think, is that Congress wanted to ensure that any state prison that accepted federal funds -- this is the heartland of the law -- provided greater accommodations, provided pre-Smith protections, and damages were vital to the pre-Smith scheme, as Tanzin made clear."}]},{"t":"case","label":"Franklin v. Gwinnett Cnty. Pub. Schs.","cite":"503 U.S. 60","y":1992,"id":"1991/90-918","sc":1,"by":{"0":"33, 40","1":"6, 19","3":"9, 10, 21"},"q":[{"src":"brief","b":0,"text":"absent clear direction to the contrary by Congress, the federal courts have the power to award any appropriate relief,","cite":"503 U.S. at 66"},{"src":"brief","b":0,"text":"Congress surely did not intend for federal moneys to be expended to support the intentional actions it sought by statute to proscribe.","cite":"503 U.S. at 75"},{"src":"brief","b":1,"text":"context here—where the defendant is a sovereign—suggests, if anything, that monetary damages are not ‘suitable’ or ‘proper.’","cite":"503 U.S. 60"},{"src":"argument","who":"Mr. Tripp","text":"Then, at that point, the -- the Franklin presumption kicks in because you have a cause of action against a non-sovereign, and -- and the ordinary rule at that point is, where there's a right, there's a remedy, right?"},{"src":"argument","who":"Mr. Tripp","text":"I think there's also some suggestion, if you compare Franklin and Sossamon, that the clear notice standard on the spending side is not as demanding as the sovereign immunity, but I think you don't need to get into that because the -- the contextual difference is so -- is so clear."},{"src":"argument","who":"Justice Sotomayor","text":"And your argument, I believe, is that Tanzin says that appropriate relief against individuals always includes damages. So does Franklin and a long list of our -- of our jurisprudence, correct?"}]},{"t":"case","label":"Guerini Stone Co. v. P.J. Carlin Constr. Co.","cite":"240 U.S. 264","y":1916,"id":"scdb/1915-098","sc":1,"by":{"0":"48"}},{"t":"case","label":"Hall v. Hall","cite":"584 U.S. 59","y":2018,"id":"2017/16-1150","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"is obviously transplanted from another legal source … it brings the old soil with it.","cite":"584 U.S. 59, 73"}]},{"t":"case","label":"Health & Hosp. Corp. of Marion Cnty. v. Talevski","cite":"599 U.S. 166","y":2023,"id":"2022/21-806","sc":1,"by":{"0":"47","1":"28, 29","2":"23","3":"10, 19"},"q":[{"src":"brief","b":1,"text":"statutes create individual rights only in ‘atypical case[s].’","cite":"599 U.S. 166, 183"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"is nothing more than a contractual offer.","cite":"599 U. S., at 196"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"Other examples, spanning Jackson, J., dissenting virtually every domain of national and state policy, abound.","cite":"599 U. S., at 198"}]},{"t":"case","label":"Holt v. Hobbs","cite":"574 U.S. 352","y":2015,"id":"2014/13-6827","sc":1,"by":{"0":"5, 6, 17, 22","1":"4, 12, 14, 18","2":"43, 44","3":"12"},"q":[{"src":"brief","b":0,"text":"neutral, generally applicable laws that incidentally burden 6 the exercise of religion usually do not violate the Free Exercise Clause.","cite":"574 U.S. at 356"},{"src":"brief","b":0,"text":"invokes congressional authority under the Spending and Commerce Clauses.","cite":"574 U.S. at 357"},{"src":"brief","b":1,"text":"in order to provide greater protection for religious exercise.","cite":"574 U.S. 352, 357"},{"src":"brief","b":2,"text":"Congress mandated that this concept ‘shall be construed in favor of a broad protection of religious exercise, to the maximum extent permitted by the terms of this chapter and the Constitution.’","cite":"574 U.S. 352, 358"}]},{"t":"case","label":"Jackson v. Birmingham Bd. of Educ.","cite":"544 U.S. 167","y":2005,"id":"2004/02-1672","sc":1,"by":{"0":"16, 29"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"by":{"0":"30"}},{"t":"case","label":"(vi) Lewis v. Clarke","cite":"581 U.S. 155","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/155/","sc":1,"by":{"0":"25"},"q":[{"src":"brief","b":0,"text":"Personal-capacity suits … seek to impose individual liability upon a government officer for actions taken under color of state law.","cite":"581 U.S. 155, 162"}]},{"t":"case","label":"Little Sisters of the Poor v. Pennsylvania","cite":"591 U.S. 657","y":2020,"id":"2019/19-431","sc":1,"by":{"0":"17"}},{"t":"case","label":"Madison v. Virginia","cite":"474 F.3d 118","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/474/118/","by":{"0":"34"}},{"t":"case","label":"United States ex rel. Marcus v. Hess","cite":"317 U.S. 537","y":1943,"id":"scdb/1942-043","sc":1,"by":{"0":"15, 40, 41, 43, 45","1":"30"},"q":[{"src":"argument","who":"Mr. Tripp","text":"I know that in Hess, United States, Marcus ex rel. Hess, that's a situation where you're reaching somebody who's a subcontractor through sort of the chain of privity."}]},{"t":"case","label":"McCulloch v. Maryland","cite":"17 U.S. 316","y":1819,"id":"1789-1850/17us316","sc":1,"by":{"0":"36, 37, 38","3":"16"},"q":[{"src":"brief","b":0,"text":"all means which are appropriate, which are plainly adapted to that end, which are not prohibited, but consist with the letter and spirit of the constitution, are constitutional.","cite":"17 U.S. at 421"},{"src":"brief","b":0,"text":"that one particular mode of effecting the object is excepted, take upon themselves the burden of establishing that exception.","cite":"17 U.S. at 409"}]},{"t":"case","label":"Medina v. Planned Parenthood S. Atl.","cite":"145 S. Ct. 2219","y":2025,"id":"2024/23-1275","sc":1,"by":{"0":"41","1":"28, 29","2":"3, 41, 48, 49, 51"},"q":[{"src":"brief","b":0,"text":"really more like treaties ‘between two sovereignties.’","cite":"145 S. Ct. 2219, 2231"},{"src":"brief","b":1,"text":"belongs to the people’s elected representatives.","cite":"145 S. Ct. at 2229"},{"src":"brief","b":2,"text":"[S]pending-power conditions are legitimate only if the State’s acceptance of them is in fact voluntary.","cite":"145 S. Ct. at 2232 n.4"},{"src":"brief","b":2,"text":"Today, all 50 States participate in Medicaid.","cite":"145 S. Ct. at 2226"},{"src":"argument","who":"Justice Gorsuch","text":"Well, in fact, in Medina, we said the Spending Clause adds a layer to 1983. And in terms of notice and consent, suppose a federal statute said something like this: If a coach at a federal funds-receiving university allows biological men on a women's sports team, a female trying to make the team could sue for a million dollars."},{"src":"argument","who":"Ms. Baird","text":"I think, here, it makes it an easier case under the Spending Clause, unlike all of the cases where the Court has considered like in Medina --"},{"src":"argument","who":"Ms. Baird","text":"So I think it would be what is the notice as provided by the statute. In Medina, I think it was Footnote 8, the Court said we care about notice as provided by Congress. So --"}]},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"by":{"0":"35","2":"5, 25, 27, 48, 51"},"q":[{"src":"brief","b":0,"text":"directly command[ing] a State to regulate or indirectly coerc[ing] a State to 35 adopt a federal regulatory system as its own.","cite":"567 U.S. 519, 577-78"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"undermine the structure of [the federal] government established by the Constitution.","cite":"567 U. S., at 559"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"proper means for carrying into [e]xecution","cite":"567 U. S., at 559"}]},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"by":{"0":"36"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"AGUI�AGA: I believe we have about four circuits post-Tanzin, Your Honor, and that includes Chief Judge Sutton in Ali versus Adamson, that includes Judge Sullivan in the Tripathy case out of New York."}]},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"0":"24"}},{"t":"case","label":"Parkell v. Senato","cite":"704 F. App’x 122","y":2017,"court":"3d Cir. Jul 11","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/704/122/","by":{"0":"22"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"by":{"0":"16","1":"22","2":"9"},"q":[{"src":"brief","b":1,"text":"Congress must express clearly its intent to impose conditions on the grant of federal funds so that the States can knowingly decide whether or not to accept those funds.","cite":"451 U.S. 1, 17, 24"},{"src":"brief","b":2,"text":"[L]egislation enacted pursuant to the spending power is much in the nature of a contract: in return for federal funds, the [recipients] agree to comply with federally imposed conditions.","cite":"451 U.S. 1, 17"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"much in the nature of a contract.","cite":"451 U. S. 1, 17"},{"src":"argument","who":"Chief Justice Roberts","text":"His view of the Spending Clause would mean that foundational cases like Pennhurst and Cummings were confused, Mr. Chief Justice, because Congress can actually impose spending conditions on non-recipients too."},{"src":"argument","who":"Justice Jackson","text":"AGUI�AGA: Your Honor, it matters here because of cases like Cummings that trace all the way back to Pennhurst that say the very legitimacy of Congress's exercise of Spending Clause authority depends on that bilateral agreement."}]},{"t":"case","label":"Ramirez v. Collier","cite":"595 U.S. 411","y":2022,"id":"2021/21-5592","sc":1,"by":{"0":"17","1":"14, 17","2":"44"}},{"t":"case","label":"Randolph v. Donaldson","cite":"13 U.S. 76","y":1815,"id":"scdb/1815-010","sc":1,"by":{"0":"44","2":"21"},"q":[{"src":"brief","b":0,"text":"[t]he keeper becomes responsible for his own acts, and may expose himself by misconduct to the ‘pains and penalties’ of the law.","cite":"13 U.S. 76, 86"}]},{"t":"case","label":"Robbins v. Robertson","cite":"2022 WL 80476","y":2022,"court":"M.D. Ga. Jan. 6","by":{"0":"22"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"the language itself, the specific context in which that language is used, and the broader context of the statute as a whole.","cite":"519 U.S. 337, 341"}]},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"by":{"0":"4, 13, 32, 48","1":"27","2":"46","3":"18, 19"},"q":[{"src":"brief","b":0,"text":"perform their duties in accordance with the [funding’s] restrictions.","cite":"500 U.S. 173, 198-99"},{"src":"brief","b":0,"text":"must perform their duties in accordance with the regulation’s restrictions.","cite":"500 U.S. at 198"},{"src":"brief","b":2,"text":"The ‘consequence of their decision to accept employment in [such] a project’ is that they must ‘perform their duties in accordance with the [funding’s] restrictions.’","cite":"500 U.S. at 198"},{"src":"brief","b":3,"text":"Individuals who are voluntarily employed for a [federally funded] project must perform their duties in accordance with [Congress’s] restrictions[.]","cite":"500 U.S. 173, 198-99"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"a consequence of their decision to accept employment.","cite":"500 U. S. 173, 199"},{"src":"argument","who":"Mr. Tripp","text":"It's indirect, right, because the officer -- and -- and what this Court said in -- in Rust is that if a person goes to work for a federally funded program, then they take the job subject to the conditions that Congress has attached to the funds."},{"src":"argument","who":"Mr. Tripp","text":"-- in Rust versus Sullivan and then in Alden versus Maine as to state officers specifically is, when you go into this job, when you go into this line of work and you voluntarily agree to be an officer in a federally funded state program, then, yes, you -- you -- you implicitly -- you necessarily take it subject to the conditions that Congress has attached to the funds."},{"src":"argument","who":"Mr. Tripp","text":"I -- I think the -- the piece about being an employee -- and this is what's picked up in Rust versus Sullivan and Alden versus Maine as to state officers in particular, who also take an oath to comply with the federal Constitution and laws -- is that you are sort of taking the job sort of subject to the conditions, the sort of terms that attach to the work."}]},{"t":"case","label":"(vii) Sabri v. United States","cite":"541 U.S. 600","y":2004,"id":"2003/03-44","sc":1,"by":{"0":"4, 11, 14, 32, 35, 36, 39, 41","1":"10, 13, 27, 31-33","2":"24, 25, 26, 27","3":"14, 16, 18, 19"},"q":[{"src":"brief","b":0,"text":"bringing federal economic might to bear on a State’s own choices of public policy.","cite":"541 U.S. at 608"},{"src":"brief","b":1,"text":"corresponding authority under the Necessary and Proper Clause to see to it that taxpayer dollars appropriated under that power","cite":"541 U.S. 600, 605"},{"src":"brief","b":1,"text":"bound up with congressional authority to spend in the first place.","cite":"541 U.S. at 608"},{"src":"brief","b":2,"text":"who convert public spending into unearned gain.","cite":"541 U.S. at 608"},{"src":"brief","b":2,"text":"is bound up with congressional authority to spend in the first place.","cite":"541 U.S. at 608"},{"src":"argument","who":"Mr. Tripp","text":"And so I think it's that sort of the -- the -- the chain of privity is the thing that makes this case sort of considerably easier, I think, than a case like Sabri or some others where you're trying to reach somebody who's a member of the general public, because these -- these are not members of the general public."},{"src":"argument","who":"Mr. Tripp","text":"I think this Court's cases go farther. Mr. Sabri did not consent."},{"src":"argument","who":"Mr. Tripp","text":"And I think what they haven't come up with is any kind of reasoned explanation why Congress can impose the condition on them but then can't enforce it, especially through civil liability, when this Court in Salinas, Dixson, Hess, and Laudani has -- has already done that and actually gone farther, and I think Sabri goes considerably farther."}]},{"t":"case","label":"42, 43, 49 Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"by":{"0":"2, 4, 14, 31, 38, 39, 41, 43, 49","1":"27, 32","2":"24","3":"3, 13, 14, 15, 16, 18, 19"},"q":[{"src":"brief","b":0,"text":"no serious doubt about [RLUIPA’s] constitutionality.","cite":"522 U.S. at 60"},{"src":"brief","b":1,"text":"was a threat to the integrity and proper operation of the federal program.","cite":"522 U.S. 52, 54-55, 60-61"},{"src":"brief","b":2,"text":"no serious doubt about the constitutionality of § 666(a)(1)(B) as applied to the facts of [that] case,","cite":"522 U.S. 52, 60"},{"src":"brief","b":3,"text":"the integrity and proper operation of the federal program.","cite":"522 U.S. 52, 60-61"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"the integrity and proper operation of the federal program.","cite":"522 U. S. 52, 61"},{"src":"argument","who":"Mr. Tripp","text":"And this Court has already held in Salinas that officers in a federally funded state prison can be held individually liable for misconduct that threatens the integrity or proper operation of the program, and that describes this case to a \"T.\" So RLUIPA is clear, it's constitutional, and we're asking the Court to reverse."},{"src":"argument","who":"Mr. Tripp","text":"One is to follow the path that this Court has set forth in -- in Salinas in particular, Salinas, Dixson, Laudani, and Hess, and to just hold that --"},{"src":"argument","who":"Justice Thomas","text":"What was Salinas about?"}]},{"t":"case","label":"Schimmelpennich v. Bayard","cite":"26 U.S. 264","y":1828,"id":"scdb/1828-043","sc":1,"by":{"0":"31"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"[W]hen Congress uses the same language in two statutes having similar purposes, particularly when one is enacted shortly after the other, it is appropriate to presume that Congress intended that text to have the same meaning in both statutes.","cite":"544 U.S. 228, 233"}]},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"by":{"0":"8, 11, 13, 19, 23, 24, 27, 28","1":"2, 5-7, 12, 13, 16, 19, 20, 25","2":"4, 29, 34, 38, 39, 40, 43, 48","3":"11"},"q":[{"src":"brief","b":0,"text":"the only form of relief that can remedy some RFRA violations.","cite":"563 U.S. 277"},{"src":"brief","b":0,"text":"been clear ‘not to imply that 41 suits under Spending Clause legislation are suits in contract, or that contract-law principles apply to all issues that they raise.’","cite":"563 U.S. at 290"},{"src":"brief","b":1,"text":"the word ‘appropriate’ is inherently context dependent.","cite":"563 U.S. at 286"},{"src":"brief","b":1,"text":"[t]hose cases did not involve sovereign defendants.","cite":"563 U.S. at 289 n.6"},{"src":"brief","b":2,"text":"do not traditionally confer a right of action for damages to enforce compliance.","cite":"563 U.S. at 290"},{"src":"brief","b":2,"text":"expressly limits the United States to ‘injunctive or declaratory relief’ to enforce the statute.","cite":"563 U.S. at 287"},{"src":"brief","b":3,"text":"do not traditionally confer a right of action for damages.","cite":"563 U.S. 277, 290"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"an express private cause of action","cite":"563 U. S., at 282"}]},{"t":"case","label":"29, 30, 41 South Dakota v. Dole","cite":"483 U.S. 203","y":1987,"id":"1986/86-260","sc":1,"by":{"0":"11, 13, 33, 34, 36, 39, 41, 42","1":"3, 11, 12, 22-24, 27, 31","2":"20","3":"9, 15, 18, 19, 20"},"q":[{"src":"brief","b":1,"text":"courts should defer substantially to the judgment of Congress.","cite":"483 U.S. at 207"},{"src":"brief","b":1,"text":"independent bar to the conditional grant of federal funds","cite":"483 U.S. at 208"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"other constitutional provisions may provide an independent bar.","cite":"483 U. S., at 207"}]},{"t":"case","label":"43, 49 Tanzin v. Tanvir","cite":"592 U.S. 43","y":2020,"id":"2020/19-71","sc":1,"by":{"0":"1, 2, 3, 4, 6, 7, 8, 11, 12, 14","1":"2, 3, 7, 8, 11-13, 15-17, 21, 24, 26","2":"1, 2, 4, 7, 8, 28, 36, 38, 39, 41, 42","3":"2, 3, 4, 5, 6, 7, 8, 10, 12"},"q":[{"src":"brief","b":0,"text":"both the pre-Smith substantive protections of the First 2 Amendment and the right to vindicate those protections by a claim.","cite":"592 U.S. at 50"},{"src":"brief","b":0,"text":"both the pre-Smith substantive protections of the First Amendment and the right to vindicate those protections by a claim.","cite":"592 U.S. at 50"},{"src":"brief","b":1,"text":"the same phrase in RFRA had been interpreted [by lower courts] not to include damages relief against the Federal Government or the States.","cite":"592 U.S. 43"},{"src":"brief","b":1,"text":"remain an appropriate form of relief today.","cite":"592 U.S. at 49"},{"src":"brief","b":2,"text":"to the actual person ‘who is invested with an office.’","cite":"592 U.S. at 47"},{"src":"brief","b":2,"text":"nonofficials acting under color of [State] law,","cite":"592 U.S. at 48"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"RFRA made clear that it was reinstating both the pre-Smith substantive protections of the First Amendment and the right to vindicate those protections by a claim.","cite":"592 U. S., at 50"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"In the context of suits against Government offcials, damages have long been awarded as appropriate relief.","cite":"592 U. S., at 49"}]},{"t":"case","label":"16, 18, 19, 20, 23, 24, 25, 27, 29, 36, 37, 38 Truck Ins. Exch. v. Kaiser Gypsum Co.","cite":"602 U.S. 268","y":2024,"id":"2023/22-1079","sc":1,"by":{"0":"16","3":"6"},"q":[{"src":"brief","b":0,"text":"text, structure, context, history, and purpose.","cite":"602 U.S. 268, 279 n.4"},{"src":"brief","b":3,"text":"the text, structure, context, history, and purpose.","cite":"602 U.S. 268, 279 n.4"}]},{"t":"case","label":"United States v. Butler","cite":"297 U.S. 1","y":1936,"id":"1900-1940/297us1","sc":1,"by":{"0":"33","2":"21"}},{"t":"case","label":"United States v. Comstock","cite":"560 U.S. 126","y":2010,"id":"2009/08-1224","sc":1,"by":{"0":"36, 37","2":"23, 25, 28"},"q":[{"src":"brief","b":0,"text":"broad power to enact laws that are ‘convenient, or useful’ or ‘conducive’ to the [principal] authority’s ‘beneficial exercise.’","cite":"560 U.S. 126, 133-34"},{"src":"brief","b":2,"text":"implied power to criminalize any conduct that might interfere with the exercise of an enumerated power.","cite":"560 U.S. 126, 147"},{"src":"brief","b":2,"text":"It is of fundamental importance to consider whether essential attributes of state sovereignty are compromised by the assertion of federal power under the Necessary and Proper Clause ....","cite":"560 U.S. at 153"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"we look to see whether the statute constitutes a means that is rationally related to the implementation of a constitutionally enumerated power.","cite":"560 U. S. 126, 134"}]},{"t":"case","label":"United States v. Gooding","cite":"25 U.S. 460","y":1827,"id":"scdb/1827-045","sc":1,"by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"Whatever the agent does, within the scope of his authority, binds his principal, and is deemed his act.","cite":"25 U.S. 460, 469"}]},{"t":"case","label":"United States v. Hall","cite":"98 U.S. 343","y":1879,"id":"scdb/1878-082","sc":1,"by":{"0":"40","2":"25"}},{"t":"case","label":"United States v. Laudani","cite":"320 U.S. 543","y":1944,"id":"scdb/1943-050","sc":1,"by":{"0":"15, 40, 45","1":"30"},"q":[{"src":"argument","who":"Mr. Tripp","text":"One is to follow the path that this Court has set forth in -- in Salinas in particular, Salinas, Dixson, Laudani, and Hess, and to just hold that --"},{"src":"argument","who":"Mr. Tripp","text":"And I think that's why, when this Court has had these cases, Salinas, Dixson, Hess, Laudani, it's a whole line of cases involving officers, agents, employees, subcontractors, where there's this chain of privity --"},{"src":"argument","who":"Mr. Tripp","text":"And I think what they haven't come up with is any kind of reasoned explanation why Congress can impose the condition on them but then can't enforce it, especially through civil liability, when this Court in Salinas, Dixson, Hess, and Laudani has -- has already done that and actually gone farther, and I think Sabri goes considerably farther."}]},{"t":"case","label":"United States v. United Mine Workers of Am.","cite":"330 U.S. 258","y":1947,"id":"scdb/1946-060","sc":1,"by":{"0":"32"}},{"t":"case","label":"United States v. Wallace & Tiernan Co.","cite":"336 U.S. 793","y":1949,"id":"scdb/1948-071","sc":1,"by":{"0":"10"},"q":[{"src":"brief","b":0,"text":"ended this suit so far as the District Court was concerned.","cite":"336 U.S. 793, 795 n.1"}]},{"t":"case","label":"(viii) Walker v. City of Birmingham","cite":"388 U.S. 307","y":1967,"id":"1966/249","sc":1,"by":{"0":"32"}},{"t":"case","label":"Ware v. La. Dep’t of Corr.","cite":"866 F.3d 263","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/866/263/","by":{"0":"8, 9, 20, 22","1":"8","2":"44"}},{"t":"case","label":"West Virginia v. EPA","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"It is a fundamental canon of statutory construction that the words of a statute must be read in their context and with a view to their place in the overall statutory scheme.","cite":"597 U.S. 697, 721"}]},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 420","y":2000,"id":"1999/99-6615","sc":1,"by":{"0":"27"}},{"t":"const","label":"Article I, Section 8, Clause 1","clauses":[["taxing-spending","Taxing and Spending Clause"]],"text":"The Congress shall have Power To lay and collect Taxes, Duties, Imposts and Excises, to pay the Debts and provide for the common Defence and general Welfare of the United States; but all Duties, Imposts and Excises shall be uniform throughout the United States;","by":{"0":"33"}},{"t":"const","label":"Article I, Section 8, Clause 18","clauses":[["necessary-proper","Necessary and Proper Clause"]],"text":"To make all Laws which shall be necessary and proper for carrying into Execution the foregoing Powers, and all other Powers vested by this Constitution in the Government of the United States, or in any Department or Officer thereof.","by":{"0":"36","3":"15, 17"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"0":"34, 35"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","subs":["(a)"],"by":{"0":"45"}},{"t":"usc","label":"42 U.S.C. § 1395dd","url":"https://www.law.cornell.edu/uscode/text/42/1395dd","subs":["(d)(1)(B)"],"by":{"0":"46","1":"30, 30"}},{"t":"usc","label":"42 U.S.C. § 300a-8","url":"https://www.law.cornell.edu/uscode/text/42/300a-8","by":{"0":"46","1":"30"}},{"t":"law","label":"Pub. L. No. 103-141","url":"https://www.govinfo.gov/link/statute/107/1489","by":{"0":"6"}},{"t":"usc","label":"42 U.S.C. § 2000bb","url":"https://www.law.cornell.edu/uscode/text/42/2000bb","by":{"0":"1","1":"2"},"q":[{"src":"brief","b":0,"text":"obtain appropriate relief against a government.","cite":"42 U.S.C. 2000bb"},{"src":"brief","b":0,"text":"other person acting under color of","cite":"42 U.S.C. 2000bb"},{"src":"brief","b":1,"text":"a State, or a subdivision of a State.","cite":"42 U.S.C. 2000bb"},{"src":"brief","b":1,"text":"obtain appropriate relief against a government,","cite":"42 U.S.C. 2000bb"}]},{"t":"usc","label":"42 U.S.C. § 2000bb-1","url":"https://www.law.cornell.edu/uscode/text/42/2000bb-1","subs":["(a)","(b)","(c)"],"by":{"0":"6","1":"4, 4, 2, 4, 15","2":"2"},"q":[{"src":"brief","b":0,"text":"obtain appropriate relief against a government.","cite":"42 U.S.C. 2000bb-1(c)"},{"src":"brief","b":1,"text":"obtain appropriate relief against a government,","cite":"42 U.S.C. 2000bb-1(c)"}]},{"t":"usc","label":"42 U.S.C. § 2000bb-2","url":"https://www.law.cornell.edu/uscode/text/42/2000bb-2","subs":["(1)"],"by":{"0":"7, 17","1":"4, 4, 15, 16","2":"7"},"q":[{"src":"brief","b":0,"text":"other person acting under color of","cite":"42 U.S.C. 2000bb-2(1)"},{"src":"brief","b":1,"text":"a State, or a subdivision of a State.","cite":"42 U.S.C. 2000bb-2(1)"},{"src":"brief","b":1,"text":"a branch, department, agency, instrumentality, and official (or other person acting under color of law) of the United States, or of a covered entity,","cite":"42 U.S.C. 2000bb-2(1)"},{"src":"brief","b":2,"text":"a branch, department, agency, instrumentality, and official (or other person acting under color of law) of the United States.","cite":"42 U.S.C. § 2000bb-2(1)"}]},{"t":"usc","label":"42 U.S.C. § 2000cc","url":"https://www.law.cornell.edu/uscode/text/42/2000cc","subs":["(a)"],"stext":{"head":"§2000cc. Protection of land use as religious exercise","paras":[[0,"(a) Substantial burdens"],[0,"(1) General rule"],[1,"No government shall impose or implement a land use regulation in a manner that imposes a substantial burden on the religious exercise of a person, including a religious assembly or institution, unless the government demonstrates that imposition of the burden on that person, assembly, or institution—"],[2,"(A) is in furtherance of a compelling governmental interest; and"],[2,"(B) is the least restrictive means of furthering that compelling governmental interest."],[0,"(2) Scope of application"],[1,"This subsection applies in any case in which—"],[2,"(A) the substantial burden is imposed in a program or activity that receives Federal financial assistance, even if the burden results from a rule of general applicability;"],[2,"(B) the substantial burden affects, or removal of that substantial burden would affect, commerce with foreign nations, among the several States, or with Indian tribes, even if the burden results from a rule of general applicability; or"],[2,"(C) the substantial burden is imposed in the implementation of a land use regulation or system of land use regulations, under which a government makes, or has in place formal or informal procedures or practices that permit the government to make, individualized assessments of the proposed uses for the property involved."],[0,"(b) Discrimination and exclusion"],[0,"(1) Equal terms"],[1,"No government shall impose or implement a land use regulation in a manner that treats a religious assembly or institution on less than equal terms with a nonreligious assembly or institution."],[0,"(2) Nondiscrimination"],[1,"No government shall impose or implement a land use regulation that discriminates against any assembly or institution on the basis of religion or religious denomination."],[0,"(3) Exclusions and limits"],[1,"No government shall impose or implement a land use regulation that—"],[2,"(A) totally excludes religious assemblies from a jurisdiction; or"],[2,"(B) unreasonably limits religious assemblies, institutions, or structures within a jurisdiction."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000cc?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1","1":"1, 4, 5"},"q":[{"src":"brief","b":0,"text":"program or activity that receives Federal financial assistance.","cite":"42 U.S.C. 2000cc"},{"src":"brief","b":0,"text":"substantial burden affects, or removal of that substantial burden would affect, commerce with foreign nations, among the several States, or with Indian tribes.","cite":"42 U.S.C. 2000cc"},{"src":"brief","b":1,"text":"commerce with foreign nations, among the several States, or with Indian tribes.","cite":"42 U.S.C. 2000cc"},{"src":"brief","b":1,"text":"imposed in a program or activity that receives Federal financial assistance.","cite":"42 U.S.C. 2000cc"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"person acting under color of State law,","cite":"42 U. S. C. §§ 2000cc"}]},{"t":"usc","label":"42 U.S.C. § 2000cc-1","url":"https://www.law.cornell.edu/uscode/text/42/2000cc-1","subs":["(a)","(b)(1)","(b)(2)","(b)"],"stext":{"head":"§2000cc–1. Protection of religious exercise of institutionalized persons","paras":[[0,"(a) General rule"],[0,"No government shall impose a substantial burden on the religious exercise of a person residing in or confined to an institution, as defined in section 1997 of this title, even if the burden results from a rule of general applicability, unless the government demonstrates that imposition of the burden on that person—"],[1,"(1) is in furtherance of a compelling governmental interest; and"],[1,"(2) is the least restrictive means of furthering that compelling governmental interest."],[0,"(b) Scope of application"],[0,"This section applies in any case in which—"],[1,"(1) the substantial burden is imposed in a program or activity that receives Federal financial assistance; or"],[1,"(2) the substantial burden affects, or removal of that substantial burden would affect, commerce with foreign nations, among the several States, or with Indian tribes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000cc-1?type=usc&year=mostrecent&link-type=html"},"by":{"0":"6, 16, 6","1":"4, 5, 12, 23, 29, 5, 5","2":"29, 48, 51"},"q":[{"src":"brief","b":0,"text":"program or activity that receives Federal financial assistance.","cite":"42 U.S.C. 2000cc-1(a)"},{"src":"brief","b":0,"text":"substantial burden affects, or removal of that substantial burden would affect, commerce with foreign nations, among the several States, or with Indian tribes.","cite":"42 U.S.C. 2000cc-1(b)(2)"},{"src":"brief","b":1,"text":"commerce with foreign nations, among the several States, or with Indian tribes.","cite":"42 U.S.C. 2000cc-1(b)"},{"src":"brief","b":1,"text":"imposed in a program or activity that receives Federal financial assistance.","cite":"42 U.S.C. 2000cc-1(b)(1)"},{"src":"brief","b":2,"text":"in any case in which ... the substantial burden is imposed in a program or activity that receives Federal financial assistance.","cite":"42 U.S.C. § 2000cc-1(b)(1)"}]},{"t":"usc","label":"42 U.S.C. § 2000cc-2","url":"https://www.law.cornell.edu/uscode/text/42/2000cc-2","subs":["(a)","(f)","(e)"],"stext":{"head":"§2000cc–2. Judicial relief","paras":[[0,"(a) Cause of action"],[0,"A person may assert a violation of this chapter as a claim or defense in a judicial proceeding and obtain appropriate relief against a government. Standing to assert a claim or defense under this section shall be governed by the general rules of standing under article III of the Constitution."],[0,"(b) Burden of persuasion"],[0,"If a plaintiff produces prima facie evidence to support a claim alleging a violation of the Free Exercise Clause or a violation of section 2000cc of this title, the government shall bear the burden of persuasion on any element of the claim, except that the plaintiff shall bear the burden of persuasion on whether the law (including a regulation) or government practice that is challenged by the claim substantially burdens the plaintiff's exercise of religion."],[0,"(c) Full faith and credit"],[0,"Adjudication of a claim of a violation of section 2000cc of this title in a non-Federal forum shall not be entitled to full faith and credit in a Federal court unless the claimant had a full and fair adjudication of that claim in the non-Federal forum."],[0,"(d) Omitted"],[0,"(e) Prisoners"],[0,"Nothing in this chapter shall be construed to amend or repeal the Prison Litigation Reform Act of 1995 (including provisions of law amended by that Act)."],[0,"(f) Authority of United States to enforce this chapter"],[0,"The United States may bring an action for injunctive or declaratory relief to enforce compliance with this chapter. Nothing in this subsection shall be construed to deny, impair, or otherwise affect any right or authority of the Attorney General, the United States, or any agency, officer, or employee of the United States, acting under any law other than this subsection, to institute or intervene in any proceeding."],[0,"(g) Limitation"],[0,"If the only jurisdictional basis for applying a provision of this chapter is a claim that a substantial burden by a government on religious exercise affects, or that removal of that substantial burden would affect, commerce with foreign nations, among the several States, or with Indian tribes, the provision shall not apply if the government demonstrates that all substantial burdens on, or the removal of all substantial burdens from, similar religious exercise throughout the Nation would not lead in the aggregate to a substantial effect on commerce with foreign nations, among the several States, or with Indian tribes."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000cc-2?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 6, 12, 18, 19, 21, 7, 12, 24","1":"2, 4, 11, 12, 15, 23-25, 29, 20, 1, 4, 17, 18, 23","2":"2, 6, 36, 40, 40","3":"11"},"q":[{"src":"brief","b":0,"text":"other person acting under color of … law[.]","cite":"42 U.S.C. 2000cc-2(a), 2000"},{"src":"brief","b":1,"text":"be construed to amend or repeal","cite":"42 U.S.C. 2000cc-2(e)"},{"src":"brief","b":1,"text":"action[s] for injunctive or declaratory relief ,","cite":"42 U.S.C. 2000cc-2"},{"src":"brief","b":2,"text":"assert a violation of this chapter as a claim or defense in a judicial proceeding and obtain appropriate relief against a government.","cite":"42 U.S.C. § 2000cc-2(a)"},{"src":"brief","b":2,"text":"the private cause of action provides that a person may assert a violation of the statute ‘as a claim or defense.’","cite":"42 U.S.C. § 2000cc-2(a)"}]},{"t":"usc","label":"42 U.S.C. § 2000cc-3","url":"https://www.law.cornell.edu/uscode/text/42/2000cc-3","subs":["(g)","(i)"],"stext":{"head":"§2000cc–3. Rules of construction","paras":[[0,"(a) Religious belief unaffected"],[0,"Nothing in this chapter shall be construed to authorize any government to burden any religious belief."],[0,"(b) Religious exercise not regulated"],[0,"Nothing in this chapter shall create any basis for restricting or burdening religious exercise or for claims against a religious organization including any religiously affiliated school or university, not acting under color of law."],[0,"(c) Claims to funding unaffected"],[0,"Nothing in this chapter shall create or preclude a right of any religious organization to receive funding or other assistance from a government, or of any person to receive government funding for a religious activity, but this chapter may require a government to incur expenses in its own operations to avoid imposing a substantial burden on religious exercise."],[0,"(d) Other authority to impose conditions on funding unaffected"],[0,"Nothing in this chapter shall—"],[1,"(1) authorize a government to regulate or affect, directly or indirectly, the activities or policies of a person other than a government as a condition of receiving funding or other assistance; or"],[1,"(2) restrict any authority that may exist under other law to so regulate or affect, except as provided in this chapter."],[0,"(e) Governmental discretion in alleviating burdens on religious exercise"],[0,"A government may avoid the preemptive force of any provision of this chapter by changing the policy or practice that results in a substantial burden on religious exercise, by retaining the policy or practice and exempting the substantially burdened religious exercise, by providing exemptions from the policy or practice for applications that substantially burden religious exercise, or by any other means that eliminates the substantial burden."],[0,"(f) Effect on other law"],[0,"With respect to a claim brought under this chapter, proof that a substantial burden on a person's religious exercise affects, or removal of that burden would affect, commerce with foreign nations, among the several States, or with Indian tribes, shall not establish any inference or presumption that Congress intends that any religious exercise is, or is not, subject to any law other than this chapter."],[0,"(g) Broad construction"],[0,"This chapter shall be construed in favor of a broad protection of religious exercise, to the maximum extent permitted by the terms of this chapter and the Constitution."],[0,"(h) No preemption or repeal"],[0,"Nothing in this chapter shall be construed to preempt State law, or repeal Federal law, that is equally as protective of religious exercise as, or more protective of religious exercise than, this chapter."],[0,"(i) Severability"],[0,"If any provision of this chapter or of an amendment made by this chapter, or any application of such provision to any person or circumstance, is held to be unconstitutional, the remainder of this chapter, the amendments made by this chapter, and the application of the provision to any other person or circumstance shall not be affected."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000cc-3?type=usc&year=mostrecent&link-type=html"},"by":{"0":"7, 25, 30","1":"18","2":"43, 3, 29","3":"7, 12"},"q":[{"src":"brief","b":0,"text":"shall be construed in favor of a broad protection of religious exercise, to the maximum extent permitted by the terms of this chapter and the Constitution.","cite":"42 U.S.C. 2000cc-3(g)"},{"src":"brief","b":0,"text":"to the maximum extent permitted by the terms of [the Act] and the Constitution.","cite":"42 U.S.C. 2000cc-3(g)"},{"src":"brief","b":2,"text":"[t]his chapter shall be construed in favor of a broad protection of religious exercise, to the maximum extent permitted by the terms of this chapter and the Constitution,","cite":"42 U.S.C. § 2000cc-3(g)"},{"src":"brief","b":3,"text":"is held to be unconstitutional, the remainder of this chapter … shall not be af- fected.","cite":"42 U.S.C. 2000cc-3(i)"}]},{"t":"usc","label":"42 U.S.C. § 2000cc-5","url":"https://www.law.cornell.edu/uscode/text/42/2000cc-5","subs":["(4)","(4)(A)","(4)(A)(ii)","(4)(A)(iii)","(4)(B)","(6)"],"stext":{"head":"§2000cc–5. Definitions","paras":[[0,"In this chapter:"],[0,"(1) Claimant"],[1,"The term \"claimant\" means a person raising a claim or defense under this chapter."],[0,"(2) Demonstrates"],[1,"The term \"demonstrates\" means meets the burdens of going forward with the evidence and of persuasion."],[0,"(3) Free Exercise Clause"],[1,"The term \"Free Exercise Clause\" means that portion of the first amendment to the Constitution that proscribes laws prohibiting the free exercise of religion."],[0,"(4) Government"],[1,"The term \"government\"—"],[2,"(A) means—"],[3,"(i) a State, county, municipality, or other governmental entity created under the authority of a State;"],[3,"(ii) any branch, department, agency, instrumentality, or official of an entity listed in clause (i); and"],[3,"(iii) any other person acting under color of State law; and"],[2,"(B) for the purposes of sections 2000cc–2(b) and 2000cc–3 of this title, includes the United States, a branch, department, agency, instrumentality, or official of the United States, and any other person acting under color of Federal law."],[0,"(5) Land use regulation"],[1,"The term \"land use regulation\" means a zoning or landmarking law, or the application of such a law, that limits or restricts a claimant's use or development of land (including a structure affixed to land), if the claimant has an ownership, leasehold, easement, servitude, or other property interest in the regulated land or a contract or option to acquire such an interest."],[0,"(6) Program or activity"],[1,"The term \"program or activity\" means all of the operations of any entity as described in paragraph (1) or (2) of section 2000d–4a of this title."],[0,"(7) Religious exercise"],[0,"(A) In general"],[2,"The term \"religious exercise\" includes any exercise of religion, whether or not compelled by, or central to, a system of religious belief."],[0,"(B) Rule"],[2,"The use, building, or conversion of real property for the purpose of religious exercise shall be considered to be religious exercise of the person or entity that uses or intends to use the property for that purpose."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000cc-5?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 7, 17, 18, 20, 28","1":"4, 16, 34, 15, 25, 15, 16, 25, 16","2":"2, 3, 6, 8, 9, 29, 36, 37, 29, 48","3":"5, 16"},"q":[{"src":"brief","b":0,"text":"other person acting under color of … law[.]","cite":"42 U.S.C. 2000cc-5(4)(A)"},{"src":"brief","b":1,"text":"other person acting under color of State law,","cite":"42 U.S.C. 2000cc-5(4)(A)(iii)"},{"src":"brief","b":1,"text":"acting under color of State law,","cite":"42 U.S.C. 2000cc-5(4)(A)"},{"src":"brief","b":2,"text":"any other person acting under color of State law.","cite":"42 U.S.C. § 2000cc-5(4)(A)(iii)"},{"src":"brief","b":2,"text":"State, county, municipality, or other governmental entity created under the authority of a State.","cite":"42 U.S.C. § 2000cc-5(4)(A)(i)"},{"src":"brief","b":3,"text":"any other person acting under color of State law.","cite":"42 U.S.C. 2000cc-5(4)(A)"}]},{"t":"usc","label":"7 U.S.C. § 2024","url":"https://www.law.cornell.edu/uscode/text/7/2024","subs":["(b)"],"by":{"0":"45"}},{"t":"usc","label":"10 U.S.C. § 4701","url":"https://www.law.cornell.edu/uscode/text/10/4701","subs":["(c)(3)"],"by":{"0":"46"}},{"t":"usc","label":"18 U.S.C. § 666","url":"https://www.law.cornell.edu/uscode/text/18/666","subs":["(a)(1)","(a)(2)","(a)","(a)(1)(B)","(a)(1)(A)"],"by":{"0":"38, 43, 39, 43","1":"33, 27, 28, 32, 33","2":"24, 24, 25, 23, 24"},"q":[{"src":"brief","b":1,"text":"anything of value to any person,","cite":"18 U.S.C. 666(a)(2)"},{"src":"argument","who":"Ms. Baird","text":"And then I think, if -- if the Court accepts Respondents' arguments on the constitutional issues, I think that could call into question Section 666, the bribery statutes, and Sabri."}]},{"t":"usc","label":"18 U.S.C. § 1347","url":"https://www.law.cornell.edu/uscode/text/18/1347","by":{"0":"45"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","subs":["(b)(2)(A)(ii)","(a)(1)(A)"],"by":{"0":"45","1":"30, 30, 30"},"q":[{"src":"brief","b":1,"text":"made to a contractor, grantee, or other recipient.","cite":"31 U.S.C. 3729(a)(1)(A)"}]},{"t":"usc","label":"41 U.S.C. § 4712","url":"https://www.law.cornell.edu/uscode/text/41/4712","subs":["(c)(2)"],"by":{"0":"46","1":"31"}},{"t":"usc","label":"42 U.S.C. § 1320a-7b","url":"https://www.law.cornell.edu/uscode/text/42/1320a-7b","subs":["(b)(1)"],"by":{"0":"45","1":"30, 30"}},{"t":"usc","label":"42 U.S.C. § 1383a","url":"https://www.law.cornell.edu/uscode/text/42/1383a","subs":["(a)"],"by":{"0":"45"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"by":{"0":"1, 3, 5, 7, 12, 14, 18","1":"7, 15, 16, 25, 28, 29","2":"2, 4, 8, 37, 42","3":"2, 3, 4, 8, 10, 13, 19, 22"},"q":[{"src":"brief","b":1,"text":"commonly available against state and local government officials","cite":"42 U.S.C. 1983"},{"src":"brief","b":1,"text":"[t]he legal ‘backdrop against which Congress enacted’ RFRA","cite":"42 U.S.C. 1983"},{"src":"argument","who":"Mr. Tripp","text":"I mean, under Talevski, this Court held that it was enforceable under Section 1983. We also give a long list in our brief of Spending Clause actions that include civil liability running all the way back to the founding."},{"src":"argument","who":"Mr. Tripp","text":"The -- we have an amicus brief from former corrections officials who talk about how, of course, this is something that they're all trained on, everybody understands this because, under Section 1983, individual capacity damages are -- they're just the paradigmatic remedy --"},{"src":"argument","who":"Mr. Tripp","text":"This is not implied enforcement through Section 1983. This is an express right, an express remedy. It expressly runs against an individual."}]},{"t":"reg","label":"48 C.F.R. § 52.212-5","url":"https://www.ecfr.gov/current/title-48/section-52.212-5","subs":["(e)(1)"],"by":{"0":"48"}},{"t":"reg","label":"48 C.F.R. § 52.244-6","url":"https://www.ecfr.gov/current/title-48/section-52.244-6","subs":["(c)(1)"],"by":{"0":"48"}},{"t":"case","label":"Arlington Cent. Sch. Dist. Bd. of Educ. v. Murphy","cite":"548 U.S. 291","y":2006,"id":"2005/05-18","sc":1,"by":{"1":"21","2":"10, 37, 47"},"q":[{"src":"brief","b":1,"text":"Congress has broad power to set the terms on which it disburses federal money to the States.","cite":"548 U.S. 291, 296"},{"src":"brief","b":2,"text":"must [be] view[ed] ... from the perspective of a state official who is engaged in the process of deciding whether the State should accept [the] funds.","cite":"548 U.S. 291, 296"},{"src":"argument","who":"Justice Sotomayor","text":"I was surprised to hear the federal government say you look at the time of enactment, when Arlington Central, Justice Alito's opinion for the Court, and then Cummings, the Chief Justice's opinion for the Court, said you look at when the official is deciding whether to receive federal funds, what would that --"}]},{"t":"case","label":"Ashcroft v. al-Kidd","cite":"563 U.S. 731","y":2011,"id":"2010/10-98","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"[w]hen properly applied, it protects ‘all but the plainly incompetent or those who knowingly violate the law.’","cite":"563 U.S. 731, 743"}]},{"t":"case","label":"Biden v. Missouri","cite":"595 U.S. 87","y":2022,"id":"2021/21a240","sc":1,"by":{"1":"22"}},{"t":"case","label":"Booker v. Graham","cite":"974 F.3d 101","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/974/101/","by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"an inmate’s transfer from a prison facility generally moots claims for declaratory and injunctive relief against officials of that facility.","cite":"974 F.3d 101, 107"}]},{"t":"case","label":"Crawford-El v. Britton","cite":"523 U.S. 574","y":1998,"id":"1997/96-827","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"discourage[s] prisoners from filing claims that are unlikely to succeed,","cite":"523 U.S. 574, 596"}]},{"t":"case","label":"Davis v. Monroe County Bd. of Educ.","cite":"526 U.S. 629","y":1999,"id":"1998/97-843","sc":1,"by":{"1":"22","2":"12"}},{"t":"case","label":"Fulton v. City of Philadelphia","cite":"593 U.S. 522","y":2021,"id":"2020/19-123","sc":1,"by":{"1":"3"}},{"t":"case","label":"Gonzales v. Raich","cite":"545 U.S. 1","y":2005,"id":"2004/03-1454","sc":1,"by":{"1":"31"},"q":[{"src":"opinion","who":"Justice Jackson, dissenting","text":"that are not within its authority to enact in isolation.","cite":"545 U. S. 1, 39"}]},{"t":"case","label":"Helix Energy Solutions Grp., Inc. v. Hewitt","cite":"598 U.S. 39","y":2023,"id":"2022/21-984","sc":1,"by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"even the most formidable policy arguments cannot overcome","cite":"598 U.S. 39, 59"}]},{"t":"case","label":"Lomax v. Oritz-Marquez","cite":"140 S. Ct. 1721","y":2020,"id":"2019/18-8369","sc":1,"by":{"1":"20"},"q":[{"src":"brief","b":1,"text":"if he has had three or more prior suits ‘dismissed on the grounds that they were frivolous, malicious, or failed to state a claim upon which relief may be granted.’","cite":"140 S. Ct. 1721, 1723"}]},{"t":"case","label":"Opulent Life Church v. City of Holly Springs","cite":"697 F.3d 279","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/697/279/","by":{"1":"25"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"by":{"1":"17"}},{"t":"case","label":"Tanvir v. Tanzin","cite":"120 F.4th 1049","y":2024,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/120/1049/","by":{"1":"21"}},{"t":"case","label":"Warger v. Shauers","cite":"574 U.S. 40","y":2014,"id":"2014/13-517","sc":1,"by":{"1":"26"}},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"by":{"1":"20","2":"31"},"q":[{"src":"brief","b":2,"text":"[I]t is ‘difficult to imagine an activity in which a State has a stronger interest, or one that is more intricately bound up with state laws, regulations, and procedures, than the administration of its prisons.’","cite":"548 U.S. 81, 94"}]},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"3"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"4"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","by":{"1":"34","2":"11"}},{"t":"usc","label":"42 U.S.C. § 1396r","url":"https://www.law.cornell.edu/uscode/text/42/1396r","subs":["(b)(3)(B)(i)","(b)(3)(B)(ii)"],"by":{"1":"29, 29, 29"}},{"t":"law","label":"Pub. L. No. 104-134","url":"https://www.govinfo.gov/link/plaw/104/public/134","by":{"1":"12"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","subs":["(d)(5)"],"by":{"1":"17"}},{"t":"usc","label":"28 U.S.C. § 1915","url":"https://www.law.cornell.edu/uscode/text/28/1915","subs":["(g)"],"by":{"1":"21"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(3)"],"by":{"1":"16"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(g)(1)"],"by":{"1":"17"}},{"t":"case","label":"Ala. Ass’n of Realtors v. HHS","cite":"594 U.S. 758","y":2021,"url":"https://supreme.justia.com/cases/federal/us/594/758/","sc":1,"by":{"2":"33"},"q":[{"src":"brief","b":2,"text":"requir[ing] Congress to enact exceedingly clear language if it wishes to significantly alter the balance between federal and state power[.]","cite":"594 U.S. at 764"}]},{"t":"case","label":"Ali v. Adamson","cite":"132 F.4th 924","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/132/924/","by":{"2":"1, 5, 30, 42"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"AGUI�AGA: I believe we have about four circuits post-Tanzin, Your Honor, and that includes Chief Judge Sutton in Ali versus Adamson, that includes Judge Sullivan in the Tripathy case out of New York."}]},{"t":"case","label":"Barr v. Am. Ass’n of Political Consultants, Inc.","cite":"591 U.S. 610","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/610/","sc":1,"by":{"2":"29"}},{"t":"case","label":"BFP v. Resolution Trust Corp.","cite":"511 U.S. 531","y":1994,"id":"1993/92-1370","sc":1,"by":{"2":"31"},"q":[{"src":"brief","b":2,"text":"if the Federal Government would ‘radically readjust[] the balance of state and national authority, those charged with the duty of legislating [must be] reasonably explicit’ about it.","cite":"511 U.S. 531, 544"}]},{"t":"case","label":"Bond v. United States","cite":"564 U.S. 211","y":2011,"id":"2010/09-1227","sc":1,"by":{"2":"19"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"by":{"2":"31, 32"},"q":[{"src":"brief","b":2,"text":"the well-established principle that ‘it is incumbent upon the federal courts to be certain of Congress’ intent before finding that federal law overrides’ the ‘usual constitutional balance of federal and state powers.’","cite":"572 U.S. 844, 858"},{"src":"opinion","who":"Opinion of the Court (Justice Gorsuch)","text":"`if there is some other ground upon which to dispose of the case.'","cite":"572 U. S. 844, 855"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"well-established principle . . . that normally the Court will not decide a constitutional question if there is some other ground upon which to dispose of the case.","cite":"572 U. S. 844, 855"}]},{"t":"case","label":"Ciminelli v. United States","cite":"598 U.S. 306","y":2023,"id":"2022/21-1170","sc":1,"by":{"2":"23"}},{"t":"case","label":"Coleman v. Lincoln Par. Detention Ctr.","cite":"858 F.3d 307","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/858/307/","by":{"2":"18"}},{"t":"case","label":"Dep’t of Transp. v. Ass’n of Am. R.R.","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"by":{"2":"19, 20"},"q":[{"src":"brief","b":2,"text":"wield power without owning up to the consequences.","cite":"575 U.S. at 57"}]},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"2":"33"}},{"t":"case","label":"Floyd v. Waiters","cite":"133 F.3d 786","y":1998,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/786/","by":{"2":"11"},"q":[{"src":"brief","b":2,"text":"Congress intended Title IX to be a typical contractual spending-power provision,","cite":"133 F.3d 786, 789"}]},{"t":"case","label":"Free Enterprise Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"by":{"2":"33"},"q":[{"src":"argument","who":"Justice Alito","text":"To the extent that prison officials have been doing things that violate RLUIPA but wouldn't violate the Free Exercise Clause, who's -- who is to blame for that?"}]},{"t":"case","label":"Fuqua v. Raak","cite":"120 F.4th 1346","y":2024,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/120/1346/","by":{"2":"17"}},{"t":"case","label":"Garcia v. LeBlanc","cite":"2022 WL 193019","y":2022,"court":"M.D. La. Jan. 20","by":{"2":"18"}},{"t":"case","label":"Gebser v. Lago Vista Indep. Sch. Dist.","cite":"524 U.S. 274","y":1998,"id":"1997/96-1866","sc":1,"by":{"2":"2, 10, 13"},"q":[{"src":"brief","b":2,"text":"similarly limits ‘the scope of available remedies.’","cite":"524 U.S. at 287"}]},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"by":{"2":"31"},"q":[{"src":"brief","b":2,"text":"must make its intention ... unmistakably clear in the language of the statute.","cite":"501 U.S. at 460"}]},{"t":"case","label":"Haight v. Thompson","cite":"763 F.3d 554","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/763/554/","by":{"2":"31"},"q":[{"src":"brief","b":2,"text":"appropriate to require Congress to ‘make its intention[s] ... unmistakably clear’ in the statute.","cite":"763 F.3d 554, 570"},{"src":"argument","who":"Mr. Tripp","text":"And, honestly, the first thing that I said, Judge Sutton, if you look at his opinion in Ali and also his prior opinion in Haight versus Thompson, he does not ask the question of whether there's an individual capacity action."}]},{"t":"case","label":"Hartley v. Parnell","cite":"193 F.3d 1263","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/193/1263/","by":{"2":"13, 14"}},{"t":"case","label":"Hathcock v. Cohen","cite":"287 F. App’x 793","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/287/793/","by":{"2":"15"}},{"t":"case","label":"Kelly v. United States","cite":"590 U.S. 391","y":2020,"id":"2019/18-1059","sc":1,"by":{"2":"23, 28"},"q":[{"src":"brief","b":2,"text":"Federal prosecutors may not use property fraud statutes to ‘set[] standards of disclosure and good government for local and state officials.’","cite":"590 U.S. at 403"},{"src":"brief","b":2,"text":"the Federal Government could use the criminal law to enforce (its view of) integrity in broad swaths of state and local policymaking.","cite":"590 U.S. at 404"}]},{"t":"case","label":"Kinman v. Omaha Pub. Sch. Dist.","cite":"171 F.3d 607","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/171/607/","by":{"2":"13, 16"},"q":[{"src":"brief","b":2,"text":"Title IX operates to condition ‘an offer of federal funding on a promise by the recipient not to discriminate, in what amounts essentially to a contract between the Government and the recipient of funds.’","cite":"171 F.3d 607, 610– 11"}]},{"t":"case","label":"LaVergne v. Stutes","cite":"2021 WL 2877789","y":2021,"court":"5th Cir. July 8","by":{"2":"18"}},{"t":"case","label":"Medellín v. Texas","cite":"552 U.S. 491","y":2008,"id":"2007/06-984","sc":1,"by":{"2":"42"}},{"t":"case","label":"Milon v. LeBlanc","cite":"496 F. Supp. 3d 982","y":2020,"court":"M.D. La.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/496/982/","by":{"2":"18"}},{"t":"case","label":"Moyle v. United States","cite":"603 U.S. 324","y":2024,"id":"2023/23-726","sc":1,"by":{"2":"23"},"q":[{"src":"brief","b":2,"text":"cannot be bound by terms that they never accepted","cite":"603 U.S. 324, 357"}]},{"t":"case","label":"Murphy v. Collier","cite":"587 U.S. 901","y":2019,"url":"https://supreme.justia.com/cases/federal/us/587/901/","sc":1,"by":{"2":"44"}},{"t":"case","label":"Nelson v. Miller","cite":"570 F.3d 868","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/570/868/","by":{"2":"15"}},{"t":"case","label":"NFIB v. Dep’t of Labor","cite":"595 U.S. 109","y":2022,"url":"https://supreme.justia.com/cases/federal/us/595/109/","sc":1,"by":{"2":"33"},"q":[{"src":"argument","who":"Ms. Baird","text":"I mean, NFIB is an example."}]},{"t":"case","label":"Pederson v. La. State Univ.","cite":"213 F.3d 858","y":2000,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/213/858/","by":{"2":"12, 15"}},{"t":"case","label":"Porter v. Manchester","cite":"2021 WL 389090","y":2021,"court":"M.D. La. Jan. 4","by":{"2":"18"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"by":{"2":"31"}},{"t":"case","label":"Rosa H. v. San Elizario Indep. Sch. Dist.","cite":"106 F.3d 648","y":1997,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/106/648/","by":{"2":"12, 14, 15"}},{"t":"case","label":"Rowinsky v. Bryan Indep. Sch. Dist.","cite":"80 F.3d 1006","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/80/1006/","by":{"2":"12, 13, 15"},"q":[{"src":"brief","b":2,"text":"The fact that Title IX was enacted pursuant to Congress’s spending power is evidence that it prohibits discriminatory acts only by grant recipients.","cite":"80 F.3d 1006, 1012"},{"src":"brief","b":2,"text":"[a]s an exercise of Congress’s spending power, Title IX makes funds available to a recipient in return for the recipient’s adherence to the conditions of the grant.","cite":"80 F.3d at 1012"}]},{"t":"case","label":"Sharp v. Johnson","cite":"669 F.3d 144","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/669/144/","by":{"2":"16, 24"}},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"by":{"2":"24"}},{"t":"case","label":"Smith v. Allen","cite":"502 F.3d 1255","y":2007,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/502/1255/","by":{"2":"14"}},{"t":"case","label":"Smith v. Metropolitan School District Perry Township","cite":"128 F.3d 1014","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/128/1014/","by":{"2":"12, 13, 15"},"q":[{"src":"brief","b":2,"text":"From what we have already written about the contractual nature of the liability, we think it follows that, because the contracting party is the grant-receiving local school district, a ‘Title IX claim can only be brought against a grant recipient [—that is, a local school district—] and not an individual.’","cite":"128 F.3d at 1019"},{"src":"brief","b":2,"text":"the fact that a statute ‘was enacted pursuant to Congress’s spending power is evidence that it prohibits discriminatory acts only by grant recipients.’","cite":"128 F.3d at 1019"}]},{"t":"case","label":"Snyder v. United States","cite":"603 U.S. 1","y":2024,"id":"2023/23-108","sc":1,"by":{"2":"24, 28"}},{"t":"case","label":"Sossamon v. Lone Star State of Tex.","cite":"560 F.3d 316","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/560/316/","by":{"2":"1, 15, 18, 20"},"q":[{"src":"brief","b":2,"text":"point its finger at the federal government for tying needed funds to an undesired liability.","cite":"560 F.3d at 329"}]},{"t":"case","label":"Sterling v. Narcisse","cite":"2024 WL 4356267","y":2024,"court":"E.D. La. June 27","by":{"2":"18"}},{"t":"case","label":"Stewart v. Beach","cite":"701 F.3d 1322","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/701/1322/","by":{"2":"17"}},{"t":"case","label":"Tanvir v. Tanzin","cite":"894 F.3d 449","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/894/449/","by":{"2":"17"}},{"t":"case","label":"Thomas v. Cooley","cite":"2024 WL 4537088","y":2024,"court":"W.D. La. Sept. 27","by":{"2":"18"}},{"t":"case","label":"Tripathy v. McKoy","cite":"103 F.4th 106","y":2024,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/103/106/","by":{"2":"17, 24"},"q":[{"src":"argument","who":"Justice Sotomayor","text":"AGUI�AGA: I believe we have about four circuits post-Tanzin, Your Honor, and that includes Chief Judge Sutton in Ali versus Adamson, that includes Judge Sullivan in the Tripathy case out of New York."}]},{"t":"case","label":"U.S. Forest Serv. v. Cowpasture River Preservation Ass’n","cite":"590 U.S. 604","y":2020,"url":"https://supreme.justia.com/cases/federal/us/590/604/","sc":1,"by":{"2":"33"}},{"t":"case","label":"Utility Air Reg. Grp. v. EPA","cite":"573 U.S. 302","y":2014,"id":"2013/12-1146","sc":1,"by":{"2":"33"},"q":[{"src":"brief","b":2,"text":"typically greet[s] its announcement with a measure of skepticism.","cite":"573 U.S. 302, 324"}]},{"t":"case","label":"Washington v. Gonyea","cite":"731 F.3d 143","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/731/143/","by":{"2":"17"},"q":[{"src":"brief","b":2,"text":"was enacted pursuant to Congress’ spending power, which allows the imposition of conditions, such as individual liability, only on those parties actually receiving the state funds.","cite":"731 F.3d 143, 145"}]},{"t":"case","label":"Wood v. Yordy","cite":"753 F.3d 899","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/753/899/","by":{"2":"16, 24"}},{"t":"case","label":"Ziglar v. Abbasi","cite":"582 U.S. 120","y":2017,"id":"2016/15-1358","sc":1,"by":{"2":"34, 35"},"q":[{"src":"brief","b":2,"text":"the silence of Congress is relevant ... [and] telling.","cite":"582 U.S. 120, 143–44"}]},{"t":"usc","label":"18 U.S.C. § 1343","url":"https://www.law.cornell.edu/uscode/text/18/1343","by":{"2":"23"}},{"t":"usc","label":"42 U.S.C. § 1396a","url":"https://www.law.cornell.edu/uscode/text/42/1396a","subs":["(a)"],"by":{"2":"49"}},{"t":"usc","label":"42 U.S.C. § 2000c-3","url":"https://www.law.cornell.edu/uscode/text/42/2000c-3","subs":["(i)"],"by":{"2":"9"}},{"t":"reg","label":"42 C.F.R. § 435.1010","url":"https://www.ecfr.gov/current/title-42/section-435.1010","by":{"2":"49"}},{"t":"case","label":"Biden v. Nebraska","cite":"600 U.S. 477","y":2023,"id":"2022/22-506","sc":1,"by":{"3":"9"}},{"t":"case","label":"Buckhannon Bd. & Care Home, Inc. v. W. Va. Dep’t of Health & Hum. Res.","cite":"532 U.S. 598","y":2001,"id":"2000/99-1848","sc":1,"by":{"3":"12"}},{"t":"case","label":"Grove City Coll. v. Bell","cite":"465 U.S. 555","y":1984,"id":"1983/82-792","sc":1,"by":{"3":"10"},"q":[{"src":"brief","b":3,"text":"perceived distinction between direct and indirect aid.","cite":"465 U.S. 555, 564"},{"src":"argument","who":"Mr. Tripp","text":"I mean, in -- in -- I think, in -- in Grove City College versus Bell, you're reading -- reaching an indirect recipient. In Salinas, Dixson, Hess, and Laudani, those are all situations where you're reaching --"},{"src":"argument","who":"Mr. Tripp","text":"And we've -- we've included a -- I mean, I -- I think there are these, like, five or six precedents from this Court that I just don't see how they can square their position with, Salinas, Hess, Laudani, Dixson, Grove City College versus Bell, and Sabri."},{"src":"argument","who":"Justice Jackson","text":"What about Grove City? MR. AGUI�AGA: Your Honor, I -- I don't recall the history behind Grove City, but I guess what I'd tell you is that this is an extraordinarily unique context where you have federal courts of appeals' on-point precedents both before and after RLUIPA's enactment that are, like, unanimously telling any state operating within the borders -- the regional borders of those circuits, like -- like, this is just not a thing."}]},{"t":"case","label":"Harper v. Va. Dep’t of Tax’n","cite":"509 U.S. 86","y":1993,"id":"1992/91-794","sc":1,"by":{"3":"21"}},{"t":"case","label":"Johnson v. Transp. Agency","cite":"480 U.S. 616","y":1987,"id":"1986/85-1129","sc":1,"by":{"3":"10"}},{"t":"case","label":"Leatherman v. Tarrant Cnty. Narcotics Intel. & Coordination Unit","cite":"507 U.S. 163","y":1993,"id":"1992/91-1657","sc":1,"by":{"3":"21"}},{"t":"case","label":"Lewis v. Clarke","cite":"581 U.S. 155","y":2017,"id":"2016/15-1500","sc":1,"by":{"3":"7"}},{"t":"case","label":"Marbury v. Madison","cite":"5 U.S. 137","y":1803,"id":"1789-1850/5us137","sc":1,"by":{"3":"12"}},{"t":"case","label":"McGirt v. Oklahoma","cite":"591 U.S. 894","y":2020,"id":"2019/18-9526","sc":1,"by":{"3":"21"}},{"t":"case","label":"Nitro-Lift Techs., L.L.C. v. Howard","cite":"568 U.S. 17","y":2012,"id":"2012/11-1377","sc":1,"by":{"3":"12"},"q":[{"src":"brief","b":3,"text":"[O]nce the Court has spoken, it is the duty of other courts to respect that understanding[.]","cite":"568 U.S. 17, 21"}]},{"t":"case","label":"Quarles v. United States","cite":"587 U.S. 645","y":2019,"id":"2018/17-778","sc":1,"by":{"3":"8"}},{"t":"case","label":"Rodriguez v. Compass Shipping Co.","cite":"451 U.S. 596","y":1981,"id":"1980/79-1977","sc":1,"by":{"3":"6, 10"},"q":[{"src":"brief","b":3,"text":"Congress has put down its pen, and we can neither rewrite Congress’ words nor call it back ‘to cancel half a Line.’ Our task is to interpret what Congress has said[.]","cite":"451 U.S. 596, 617 n.40"}]},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"583 U.S. 202","y":2018,"id":"2017/16-534","sc":1,"by":{"3":"12"}},{"t":"case","label":"Steffel v. Thompson","cite":"415 U.S. 452","y":1974,"id":"1973/72-5581","sc":1,"by":{"3":"6"},"q":[{"src":"brief","b":3,"text":"cannot make even an unconstitutional statute disappear.","cite":"415 U.S. 452, 469-70"}]},{"t":"case","label":"(iii) United States v. Palomar-Santiago","cite":"593 U.S. 321","y":2021,"url":"https://supreme.justia.com/cases/federal/us/593/321/","sc":1,"by":{"3":"21"},"q":[{"src":"brief","b":3,"text":"[J]udicial construction … is an authoritative statement of what the [law] meant before as well as after the decision of the case giving rise to that construction.","cite":"593 U.S. 321, 325"}]},{"t":"case","label":"United States v. Rabinowitz","cite":"339 U.S. 56","y":1950,"id":"1940-1955/339us56","sc":1,"by":{"3":"13"},"q":[{"src":"brief","b":3,"text":"how a hint becomes a suggestion, is loosely turned into dictum and finally elevated to a decision.","cite":"339 U.S. 56, 75"}]},{"t":"case","label":"Wash. State Grange v. Wash. State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"by":{"3":"22"},"q":[{"src":"brief","b":3,"text":"is unconstitutional in all of its applications,","cite":"552 U.S. at 449"}]},{"t":"case","label":"West v. Atkins","cite":"487 U.S. 42","y":1988,"id":"1987/87-5096","sc":1,"by":{"3":"22"},"q":[{"src":"brief","b":3,"text":"made possible … because the wrongdoer is clothed with the authority of state law.","cite":"487 U.S. 42, 49"}]},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","by":{"3":"8"}},{"t":"usc","label":"18 U.S.C. § 245","url":"https://www.law.cornell.edu/uscode/text/18/245","subs":["(b)(1)(E)"],"by":{"3":"17"}},{"t":"usc","label":"18 U.S.C. § 844","url":"https://www.law.cornell.edu/uscode/text/18/844","subs":["(f)"],"by":{"3":"17"}},{"t":"usc","label":"18 U.S.C. § 2242","url":"https://www.law.cornell.edu/uscode/text/18/2242","by":{"3":"17"}},{"t":"usc","label":"18 U.S.C. § 2243","url":"https://www.law.cornell.edu/uscode/text/18/2243","subs":["(a)","(b)"],"by":{"3":"17, 17"}},{"t":"usc","label":"18 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/18/2244","by":{"3":"17"}},{"t":"usc","label":"18 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/18/2255","subs":["(a)"],"by":{"3":"17"}}]};